function showBreak(after){clearInterval(timer);clearInterval(breakTimer);const state=S;if(!state)return;state.activeBreak=state.activeBreak||{after,until:Date.now()+600000};persistSession();$('#uxBreak')?.remove();Array.from($('#ux').children||[]).forEach(el=>el.setAttribute('inert',''));$('#ux').insertAdjacentHTML('beforeend',`<div class="ux-break" id="uxBreak" role="dialog" aria-modal="true"><div><h2>${ui('استراحة 10 دقائق','10-minute break')}</h2><p>${ui('مؤقت الاختبار متوقف. عند المتابعة يُغلق هذا القسم.','The exam timer is paused. Continuing locks this section.')}</p><b id="uxBreakTime"></b><div><button class="btn p" id="uxResume">${ui('متابعة الاختبار','Resume exam')}</button></div></div></div>`);let resumed=false;function resume(){if(resumed||S!==state)return;resumed=true;clearInterval(breakTimer);state.left=Math.max(0,state.left-Math.floor(Math.max(0,Date.now()-state.activeBreak.until)/1000));state.activeBreak=null;state.sectionStart=after;state.idx=after;$('#uxBreak')?.remove();render();if(state.left<=0)finish();else startTimer()}function tick(){if(S!==state)return;if(!sameOwner()){close();return}const left=Math.max(0,Math.ceil((state.activeBreak.until-Date.now())/1000));const el=$('#uxBreakTime');if(el)el.textContent=fmt(left).slice(3);if(left<=0)resume()}$('#uxResume').onclick=resume;$('#uxResume').focus?.();breakTimer=setInterval(tick,250);tick()}
function startTimer(){clearInterval(timer);let last=Date.now();timer=setInterval(()=>{if(!S||S.activeBreak)return;if(!sameOwner()){close();return}const now=Date.now();if(window.LearningLanguage?.pending){last=now;return}const elapsed=Math.floor((now-last)/1000);if(elapsed<=0)return;last+=elapsed*1000;S.left=Math.max(0,S.left-elapsed);persistSession();const e=$('#uxTime');if(e)e.textContent=fmt(S.left);if(S.left<=0){clearInterval(timer);finish()}},250)}function fmt(n){n=Math.max(0,Math.floor(n));return[Math.floor(n/3600),Math.floor(n%3600/60),n%60].map(x=>String(x).padStart(2,'0')).join(':')}
