 const feedbackButton=document.createElement('button');feedbackButton.type='button';feedbackButton.className='ux-secondary';feedbackButton.textContent=ui('قيّم الاختبار أو أرسل استفسارًا','Rate this exam or send an inquiry');feedbackButton.dataset.feedbackPackage=S.pid;feedbackButton.dataset.feedbackKind='exam';feedbackButton.dataset.feedbackId=S.eid;feedbackButton.dataset.feedbackLabel=assessmentLabel();$('#uxSaveStatus').after(feedbackButton);
